/* the Endless floor deck: crosswalk cards for the steps ∞1 to ∞86 (work/phaseJ/decks for ∞1-∞26, work/crosswalk/decks3 for ∞27-∞78, work/phaseK/decks for ∞79-∞86) */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞1"]=[{"q": "A map from A × A to B names every function from A to B. What must every function from B to B have?", "a": "a fixed point, some b with f(b) = b", "w": ["an undo", "exactly two fixed points", "no fixed point at all"], "why": "The fixed-point technique."}, {"q": "B = {true, false} and f is “not”. What does the fixed-point technique then say about A?", "a": "no map names every function from A to B", "w": ["A must be empty", "A must be finite", "every map names them all"], "why": "“Not” keeps nothing fixed, so the namer cannot exist."}, {"q": "Which result is the fixed-point technique read with B the true-or-false set and A a set?", "a": "the parts of a set outrun its members", "w": ["every set has a largest member", "two sets of one size match", "every part has a complement"], "why": "Rung 35 as one case."}, {"q": "The set of all things that are not members of themselves. What does the diagonal show?", "a": "no set holds exactly those things", "w": ["it holds itself", "it is empty", "it is the set of all sets"], "why": "Rung 2, read down the diagonal."}, {"q": "What does each diagonal argument do on the diagonal?", "a": "reads each thing at itself and takes the opposite", "w": ["counts the members twice", "adds one to every row", "sorts the rows"], "why": "One argument, five times."}, {"q": "In arithmetic the fixed-point idea gives a positive result. What is it?", "a": "a statement that speaks about itself", "w": ["a proof of every true statement", "a largest number", "a machine that decides stopping"], "why": "Rung 38’s self-reading statement."}, {"q": "If a machine decided stopping, which map would the fixed-point technique then refute?", "a": "“stop if the input loops, loop if it stops”, which keeps nothing fixed", "w": ["“add one to the output”, which keeps some value fixed", "the machine that always stops on every input", "the do-nothing machine, which keeps everything fixed"], "why": "Rung 41, read as one case."}, {"q": "The fixed-point technique. Its accepted name?", "a": "Lawvere’s fixed-point theorem", "w": ["Brouwer’s fixed-point theorem", "the Banach contraction principle", "Tarski’s fixed-point theorem"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞2"]=[{"q": "f maps X to Y and V is a part of Y. What is f⁻¹(V)?", "a": "the members of X whose outputs land in V", "w": ["the outputs of V", "the members of Y not in V", "the members of X that miss V"], "why": "Pulling back."}, {"q": "Which of these does pulling back keep?", "a": "unions, meets and the part left over", "w": ["only unions", "only meets", "none of them"], "why": "The pull-back-keeps technique."}, {"q": "f[P] ⊆ V exactly when P ⊆ f⁻¹(V). Which side of pulling back is taking images?", "a": "the left side", "w": ["the right side", "neither side", "both sides at once"], "why": "The image-left technique."}, {"q": "An output y is in f∀[P] when…", "a": "every member sent to y is in P", "w": ["some member sent to y is in P", "no member is sent to y", "y is in P"], "why": "The every-image, right of pulling back."}, {"q": "How many right sides can one map between orders have?", "a": "at most one", "w": ["exactly two", "any number", "always one"], "why": "The one-right-side technique."}, {"q": "Which quantifier sits on the left of pulling back?", "a": "some", "w": ["every", "not", "if"], "why": "Images are the some-guess from below."}, {"q": "With ◇P = s[t⁻¹(P)], how is □P written from ◇?", "a": "W ∖ ◇(W ∖ P)", "w": ["◇P ∪ P", "◇(◇P)", "W ∖ P"], "why": "The reach-modal technique: necessary and possible are the same pair."}, {"q": "Pulling back along f, written f*. Its accepted name for the set f⁻¹(V)?", "a": "the preimage or inverse image", "w": ["the direct image", "the dual image", "the fibre product"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞3"]=[{"q": "Functions from A × S to B × S match functions from A to what?", "a": "functions from S to B × S", "w": ["functions from B to S", "pairs A × B", "lists of B"], "why": "The state-wrap technique."}, {"q": "Under the maybe wrapper, g ⋆ f fails at a when…", "a": "f fails at a, or f gives b and g fails at b", "w": ["only when f and g both fail", "only when g fails at a", "never: maybe cannot fail"], "why": "The maybe-row technique."}, {"q": "What two maps must a wrapper have for wrapped programs to run in a row?", "a": "one to wrap a plain value, one to unwrap a wrapper of wrappers", "w": ["one to add two values, one to multiply them", "one to copy a value, one to delete it", "one to read a name, one to write a name"], "why": "Wrap and join."}, {"q": "A lawful wrapper’s wrapped programs, with wrap as do-nothing and ⋆ as the row. What do they form?", "a": "a category", "w": ["a ring", "a single set", "a total order"], "why": "The wrapped-category technique."}, {"q": "Which wrapper comes from freeing after forgetting for joining?", "a": "the list wrapper", "w": ["the maybe wrapper", "the state wrapper", "the chance wrapper"], "why": "The free-wrapper technique."}, {"q": "Chance rules f : A → T(B) and g : B → T(C). What does g ⋆ f give c, from a?", "a": "Σ over b of f(a)(b) · g(b)(c)", "w": ["f(a)(c) + g(a)(c)", "the largest f(a)(b)", "f(a)(b) for a single b"], "why": "The chance-row technique: a product of chance grids."}, {"q": "Where does every left-and-right pair F ⊣ U give a wrapper?", "a": "U ∘ F", "w": ["F ∘ F", "U ∘ U", "F alone"], "why": "Freeing after forgetting."}, {"q": "A lawful wrapper. Its accepted name?", "a": "a monad", "w": ["a monoid", "a functor category", "a lens"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞4"]=[{"q": "What does the chain rule say about the slope of a chain?", "a": "it is the product of the slopes along it", "w": ["it is the sum of the slopes", "it is the largest slope", "it is the first slope"], "why": "Slope-taking keeps the row."}, {"q": "Taking slope grids sends running in a row to what?", "a": "running in a row of grids, a product", "w": ["a sum of grids", "the do-nothing grid", "a single number"], "why": "The slope-map technique: a map of categories."}, {"q": "A lens has two parts. What are they?", "a": "a get forward and a put that comes back with a correction", "w": ["two gets, both going forward", "a get forward and a copy of it", "a read of the data and a delete"], "why": "From keeping two copies of data in step."}, {"q": "Two lenses in a row. What do they make?", "a": "a lens, without care for brackets", "w": ["a pair that cannot run", "a single get", "a wrapper"], "why": "The lens-chain technique."}, {"q": "A learner b = w x with error ½(b − t)². What is the knob’s slope?", "a": "(b − t) x", "w": ["(b − t) w", "b − t", "w x"], "why": "The one-step-learner technique."}, {"q": "A small enough step against a knob’s slope does what to the error?", "a": "lowers it, unless the slope is 0", "w": ["raises it", "leaves it alone", "doubles it"], "why": "Going downhill."}, {"q": "In two learners in a row, which put runs first?", "a": "the second learner’s, then the first’s", "w": ["the first learner’s", "both at once", "neither: they share one put"], "why": "The learner-chain technique: the error is carried backwards."}, {"q": "The backward pass through the layers. Its accepted name?", "a": "backpropagation, reverse-mode automatic differentiation", "w": ["forward-mode differentiation", "gradient clipping", "the Para construction"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞5"]=[{"q": "A database on a schema S, read as rung 47 did. What is it?", "a": "a map from the schema to sets", "w": ["a single table", "a list of numbers", "a function from sets to S"], "why": "Data as a map from the schema."}, {"q": "F : S → T and data J on T. What is the data moved back to S?", "a": "J ∘ F, reading through the map", "w": ["F ∘ J", "J alone", "the empty data"], "why": "The pull-data technique."}, {"q": "F sends tables A and B to one table C. What does the left move Σ put in C?", "a": "the rows of both tables side by side", "w": ["the pairs of rows", "only the rows of A", "no rows"], "why": "Gluing, left of the backward move."}, {"q": "And what does the right move Π put in C?", "a": "the pairs of rows, I(A) × I(B)", "w": ["the rows side by side", "only the rows of B", "the shared rows only"], "why": "Joining, right of the backward move."}, {"q": "Moving workers forward into a schema with teams, what does Σ do?", "a": "gives each worker a team of their own", "w": ["puts every worker on one team", "drops every worker", "asks for teams first"], "why": "The new-table technique."}, {"q": "And what does Π do there?", "a": "puts every worker on one team", "w": ["gives each worker a team of their own", "makes no teams", "doubles the workers"], "why": "The new-table technique."}, {"q": "The answers to a query with only ands and somes in data I match what?", "a": "the maps of data from the query’s pattern into I", "w": ["the rows of I", "the tables of the schema", "the maps from I into the pattern"], "why": "The query-is-map technique."}, {"q": "The forward move Σ along a map of schemas. Its accepted name?", "a": "the left Kan extension", "w": ["the right Kan extension", "the pullback", "the coproduct"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞6"]=[{"q": "On signs, what is + plus −?", "a": "⊤, sign unknown", "w": ["+", "−", "0"], "why": "Adding signs is not exact."}, {"q": "On signs, what is − times −?", "a": "+", "w": ["−", "0", "⊤"], "why": "Multiplying signs is exact."}, {"q": "The blurred run of x · x + 1 gives + for every input sign. What follows?", "a": "x · x + 1 is positive for every number x", "w": ["only for positive x", "nothing about real numbers", "it is 0 somewhere"], "why": "The sign-run technique."}, {"q": "Blur α and sharpen γ: α(A) ≤ s exactly when A ⊆ γ(s). Which is left?", "a": "blur is left of sharpen", "w": ["sharpen is left of blur", "neither", "both are right"], "why": "The blur-pair technique."}, {"q": "What does the blur-sound technique promise of the blurred run?", "a": "whatever it says covers every real run", "w": ["it is exact", "it finds every bug with no alarm", "it runs faster than the program"], "why": "f(A) ⊆ γ(f♯(α(A)))."}, {"q": "An interval end keeps moving in a loop. What does widening do to it?", "a": "sends it to ±∞, so the analysis stops", "w": ["stops the program", "rounds it to 0", "drops the loop"], "why": "The widen technique."}, {"q": "A machine check never calls an unsafe program safe. What must it then do, by rung 41?", "a": "call some safe program unsafe", "w": ["decide every program exactly", "never finish", "call every program unsafe"], "why": "The false-alarm technique."}, {"q": "Checking by running a blurred copy. Its accepted name?", "a": "abstract interpretation", "w": ["model checking", "symbolic execution", "fuzz testing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞7"]=[{"q": "Rung 41’s reading machines and rung 40’s programs with state share which shape?", "a": "a set of states with one map out, giving an output and a next state", "w": ["a list of numbers", "a tree of choices", "a single function into the states"], "why": "A machine is a map out of a set."}, {"q": "A map of stream machines sends each state to a state with what?", "a": "the same row of outputs", "w": ["a larger output", "no output", "the reverse row"], "why": "The map-keeps-outputs technique."}, {"q": "Two states tied by a relation that survives every step. What can no experiment do?", "a": "tell them apart", "w": ["run them", "count their outputs", "start them"], "why": "The bisimulation technique."}, {"q": "How many maps does every stream machine have into the streams?", "a": "exactly one", "w": ["none", "two", "one for each state"], "why": "The last-machine technique."}, {"q": "How are two streams proved equal in this step?", "a": "by showing a relation that survives every step", "w": ["by induction on length", "by checking the first output", "by counting outputs"], "why": "The relation-proof technique."}, {"q": "The image of a reading machine in the last machine. What is it?", "a": "the smallest machine for its pattern, among those with every state reachable", "w": ["the largest machine that reads the same pattern", "the empty machine, with no states", "a machine with exactly one state"], "why": "The least-machine technique."}, {"q": "If Z is a last machine for the shape F, what is its map c : Z → F(Z)?", "a": "undoable", "w": ["constant", "empty", "never one to one"], "why": "The last-is-matched technique; for “a set of nexts” it would need sets that hold themselves."}, {"q": "Proving equality with a relation that survives every step. Its accepted name?", "a": "coinduction", "w": ["induction", "recursion", "bisection"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞8"]=[{"q": "Which two free moves are taken away in this logic?", "a": "copying a given and throwing one away", "w": ["adding an option and dropping a not", "swapping and grouping", "writing x + 0 for x"], "why": "Each given is spent once."}, {"q": "In a proof with only ⊗ and ⊸, no copying and no throwing away, what is every letter’s signed count?", "a": "0", "w": ["1", "2", "the number of lines"], "why": "The balance technique."}, {"q": "Which follows from A & B?", "a": "A, and also B", "w": ["A ⊗ B", "nothing", "A ⊸ B"], "why": "The two-ands technique: & is your choice of one."}, {"q": "Does A ⊗ B give A alone?", "a": "no: B would be thrown away", "w": ["yes, always", "only when A is B", "only with a !"], "why": "Both at once must both be spent."}, {"q": "From coin ⊗ coin and coin ⊸ coffee, what can be proved?", "a": "coffee ⊗ coin", "w": ["coffee ⊗ coffee", "coin alone", "coffee alone"], "why": "The spend-to-get technique."}, {"q": "Which givens may be copied or dropped?", "a": "only those marked !", "w": ["all givens", "none ever", "only those joined by &"], "why": "The bang-copy technique."}, {"q": "For a space V other than {0}, what is v ↦ v ⊗ v?", "a": "not straight", "w": ["straight", "undoable", "constant"], "why": "The no-straight-copy technique: a quantum state cannot be copied."}, {"q": "The logic in which each given is spent once. Its accepted name?", "a": "linear logic", "w": ["intuitionistic logic", "modal logic", "relevance-free logic"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞9"]=[{"q": "What must a distance obey to be read as a category?", "a": "the detour rule and d(x, x) = 0", "w": ["symmetry only", "d(x, y) = 1 for all pairs", "the parallel rule"], "why": "The detour-is-composing technique."}, {"q": "In such a category, what is running in a row?", "a": "adding the numbers", "w": ["multiplying the numbers", "taking the larger", "taking the smaller"], "why": "Arrows are numbers."}, {"q": "A map that does not stretch. What do two in a row make?", "a": "a map that does not stretch", "w": ["a stretch by 2", "an undo", "a constant map"], "why": "The short-row technique."}, {"q": "The largest gap between d(−, x) and d(−, y) is exactly what?", "a": "d(x, y)", "w": ["0", "2 d(x, y)", "1"], "why": "The distances-to technique: a point is its distances."}, {"q": "Two points at distance d. What is the magnitude?", "a": "2/(1 + e⁻ᵈ)", "w": ["2", "1 + d", "2d"], "why": "The two-point technique."}, {"q": "Two points far apart. What does the magnitude come near?", "a": "2", "w": ["1", "0", "∞"], "why": "Far points count as two."}, {"q": "A two-point space scaled by t, as t → 0. What does the magnitude go to?", "a": "1", "w": ["2", "0", "∞"], "why": "The scale-count technique: close points count as one."}, {"q": "The number that counts how many points a space effectively has. Its accepted name?", "a": "magnitude", "w": ["Hausdorff measure", "cardinality", "diameter"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞10"]=[{"q": "A kind of structure gives, for each finite set of labels, what?", "a": "the set of structures on it, carrying relabellings along", "w": ["one number, the count of structures", "a single tree on those labels", "a list of sizes, one per label"], "why": "A map of categories."}, {"q": "The number of structures on U depends on what alone?", "a": "the size of U", "w": ["the names of the labels", "the order of the labels", "the largest label"], "why": "The size-only technique."}, {"q": "What is the shadow of F · G?", "a": "F(x) G(x)", "w": ["F(x) + G(x)", "F(G(x))", "F(x)/G(x)"], "why": "The product-shadow technique."}, {"q": "Every shuffle of U is one set of what?", "a": "cycles", "w": ["trees", "pairs", "orders"], "why": "The shuffles-are-cycles technique: S = E ∘ C."}, {"q": "Orders and shuffles both have n! on n labels. Are they the same kind for n ≥ 2?", "a": "no: no matching commutes with every relabelling", "w": ["yes, always: equal counts mean one kind", "only for n = 3", "only when n is even"], "why": "The not-the-same-kind technique."}, {"q": "How many functions are there from {1, …, n} to itself?", "a": "nⁿ", "w": ["n!", "2ⁿ", "n²"], "why": "As many as the doubly rooted trees."}, {"q": "So how many trees are there on n labels?", "a": "nⁿ⁻²", "w": ["nⁿ", "n!", "2ⁿ⁻¹"], "why": "The two-ways technique."}, {"q": "A kind of structure on labels. Its accepted name?", "a": "a combinatorial species", "w": ["a partition", "a generating set", "a graph family"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞11"]=[{"q": "In how many ways can five things be bracketed?", "a": "14", "w": ["5", "10", "42"], "why": "Counting bracketings."}, {"q": "How is B(n) found from smaller counts?", "a": "the sum of B(k) B(n − k) over the last split k", "w": ["B(n − 1) + B(n − 2), as for rabbits", "n · B(n − 1), one per place", "2 B(n − 1), bracket left or right"], "why": "The last-split technique."}, {"q": "How many single regroupings does each bracketing of n things allow?", "a": "n − 2", "w": ["n", "n − 1", "2"], "why": "The single-move technique."}, {"q": "The bracketings of four things, joined by single regroupings. What shape do they make?", "a": "a pentagon", "w": ["a square", "a triangle", "a cube"], "why": "Five corners, five edges."}, {"q": "For sets, the regrouping (A × B) × C → A × (B × C) is a matching. What else is it?", "a": "natural: it commutes with functions run on each part", "w": ["the do-nothing map on A × B × C", "a swap of A and C", "not a function at all"], "why": "The regroup-matching technique."}, {"q": "When regroupings are only matchings, what must agree for brackets not to matter?", "a": "the two routes round the pentagon", "w": ["every pair of sets", "the sizes of A, B, C", "the two sides of a triangle only"], "why": "The pentagon-route technique."}, {"q": "If the pentagon rule holds, what happens round every face of the solid for five things?", "a": "it closes: going round does nothing", "w": ["it fails on one face", "it doubles the matching", "the faces cannot be drawn"], "why": "The faces-fill technique."}, {"q": "The counts 1, 1, 2, 5, 14, 42. Their accepted name?", "a": "the Catalan numbers", "w": ["the Bell numbers", "the Fibonacci numbers", "the Stirling numbers"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞12"]=[{"q": "In a quantum circuit drawing, what does side by side mean?", "a": "the tensor product", "w": ["adding the states", "running in a row", "reading the qubit"], "why": "Boxes, wires, side by side."}, {"q": "A box on one wire and a box on another. What can they do?", "a": "slide past each other, the result unchanged", "w": ["never pass each other", "cancel each other out", "swap their wires"], "why": "The wire-slide technique."}, {"q": "A loop of wire, cap after cup. What number is it?", "a": "n, the dimension", "w": ["0", "1", "2n"], "why": "The cup-cap technique."}, {"q": "A wire bent round a cup and back round a cap. What does it equal?", "a": "a straight wire, the do-nothing", "w": ["a loop", "a cap", "zero"], "why": "The yanking technique."}, {"q": "A box A slides round a cup to the other wire. What does it become?", "a": "its transpose, Aᵀ", "w": ["A unchanged", "A⁻¹", "the do-nothing"], "why": "The slide-round-cup technique."}, {"q": "In teleportation, with what chance does each of the sender’s four readings come?", "a": "¼", "w": ["½", "1", "0"], "why": "The teleport technique."}, {"q": "Two green dots joined by one wire. What do they become?", "a": "one green dot, with the angles added", "w": ["two red dots", "a cup", "a loop with number n"], "why": "The dot-fusion technique."}, {"q": "The yanking rule. Its accepted name?", "a": "the snake equation, or zigzag identity", "w": ["the pentagon identity", "the Bell equation", "the triangle identity"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞13"]=[{"q": "How do chance rules run in a row?", "a": "by multiplying chance grids", "w": ["by adding chances", "by taking the larger chance", "by copying the input"], "why": "Rung 30’s chance grids."}, {"q": "Which chance rules pass through the copying dot?", "a": "only plain functions, one output with chance 1", "w": ["every chance rule", "no rule at all", "only fair coins, chance ½ each"], "why": "The copy-sorts technique."}, {"q": "Which chance rules pass through the ending dot?", "a": "every chance rule", "w": ["only plain functions", "none", "only constant rules"], "why": "Every chance rule ends somewhere."}, {"q": "A joint ψ makes X and Y independent exactly when…", "a": "the picture falls into two pieces, its marginals side by side", "w": ["it passes through the copying dot", "all its chances are equal", "X and Y are the same wire"], "why": "The falls-apart technique."}, {"q": "Turning a rule around, what is g(θ | x)?", "a": "f(x | θ) π(θ) divided by Σ over t of f(x | t) π(t)", "w": ["f(x | θ), the rule unchanged", "π(θ) alone, the prior unchanged", "f(θ | x) π(x)"], "why": "The turn-around technique: Bayes as a bent wire."}, {"q": "Doing t, as against seeing t, cuts which wire?", "a": "the wire into T, from its cause Z", "w": ["the wire out of Y", "every wire", "no wire"], "why": "The cut-the-wire technique."}, {"q": "When do seeing and doing agree?", "a": "when there is no wire from Z to T", "w": ["always", "never", "when Y has two values"], "why": "Cut nothing, change nothing."}, {"q": "A category of chance rules with copy and discard. Its accepted name?", "a": "a Markov category", "w": ["a Kleisli category", "a compact closed category", "a topos"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞14"]=[{"q": "Which of the three demands on a measure of surprise asks about a choice made in two stages?", "a": "the grouping demand", "w": ["continuity", "growth with equal outcomes", "symmetry"], "why": "First stage plus the average second."}, {"q": "H(¼, ¼, ½) by grouping equals what?", "a": "H(½, ½) + ½ H(½, ½)", "w": ["2 H(½, ½)", "H(½, ½)", "H(¼, ¼)"], "why": "The grouping technique."}, {"q": "H(X, Y) equals what?", "a": "H(X) + Σ over x of p(x) H(Y | X = x)", "w": ["H(X) · H(Y)", "H(X) − H(Y)", "the larger of H(X), H(Y)"], "why": "The chain-rule technique."}, {"q": "A(mn) = A(m) + A(n) and A grows with n. What is A(n)?", "a": "c log n, for a constant c ≥ 0", "w": ["c n", "n²", "c/n"], "why": "The equal-log technique."}, {"q": "The three demands force which formula?", "a": "c Σ pᵢ log(1/pᵢ)", "w": ["Σ pᵢ²", "max pᵢ", "Σ log pᵢ"], "why": "The forced-formula technique."}, {"q": "The proof runs through which chances, in order?", "a": "equal chances, then fractions, then all chances", "w": ["all chances at once", "fractions only", "two outcomes, then three"], "why": "Adding from multiplying."}, {"q": "The loss of g ∘ f, for maps that keep chances. What is it?", "a": "the loss of f plus the loss of g", "w": ["the larger of the two", "their product", "0"], "why": "The loss-adds technique."}, {"q": "Average surprise. Its accepted name?", "a": "Shannon entropy", "w": ["Kullback–Leibler divergence", "Fisher information", "Tsallis entropy"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞15"]=[{"q": "A transition of a net fires. What does it do?", "a": "eats some tokens and makes others", "w": ["moves one place", "adds a place", "copies the whole marking"], "why": "A net and its firing rule."}, {"q": "Rung 27’s balanced reaction as a net. What are the places and the tokens?", "a": "the species and the molecules", "w": ["the atoms and the bonds", "the reactions and the rates", "the vessels and the litres"], "why": "One transition per reaction."}, {"q": "y · (out(t) − in(t)) = 0 for every transition t. What follows for y · m?", "a": "it is the same at every marking reached from the start", "w": ["it grows by one each firing", "it is always 0", "it doubles"], "why": "The conserved-weight technique."}, {"q": "A marking whose conserved weight differs from the start’s. Can it be reached?", "a": "no", "w": ["yes, after enough firings", "only once", "only if the net is open"], "why": "The rule-out technique."}, {"q": "Two firings that can both fire and do not need each other’s tokens. What about the order?", "a": "either order reaches the same marking", "w": ["only one order works", "they cannot both fire", "the order doubles the tokens"], "why": "The side-by-side technique: runs are arrows."}, {"q": "Two open nets glued along ports. When is a weight on the glued net conserved?", "a": "exactly when its part on each piece is conserved", "w": ["never", "always", "only on the larger piece"], "why": "The glued-weight technique."}, {"q": "What does a conserved weight do along the rate rule of rung 13?", "a": "stays constant", "w": ["falls to 0", "grows without bound", "swings"], "why": "The rate-keeps-weight technique."}, {"q": "A conserved weight on a net. Its accepted name?", "a": "a P-invariant, or place invariant", "w": ["a T-invariant", "a siphon", "a trap"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞16"]=[{"q": "A lens with a choice in the middle. What goes forward and what comes back?", "a": "a move forward, a payoff back", "w": ["a payoff forward, a move back", "two moves", "nothing back"], "why": "A player as a lens."}, {"q": "When does a plan hold in the context (x, k)?", "a": "when its move earns at least as much under k as every other move", "w": ["when it earns the most of any player", "when every move is tried", "when k is 0"], "why": "The best-reply technique."}, {"q": "Two pieces side by side. When is a pair of moves a rest?", "a": "when each is a best reply with the other’s move held fixed", "w": ["when both players earn the same", "when the first player moves first", "never: side by side has no rest"], "why": "The side-by-side technique."}, {"q": "Two pieces in a row. Who sees what?", "a": "the second player sees the first move", "w": ["the first sees the second move", "neither sees the other", "both see the payoff in advance"], "why": "A game in a row."}, {"q": "In a row, what is fed back to the first player?", "a": "the payoff passed back through the second’s plan", "w": ["nothing", "the first player’s own move", "the second’s move only"], "why": "The in-a-row technique."}, {"q": "Best replies of two pieces chase each other round all four pairs. What follows?", "a": "the whole has no rest in plain moves", "w": ["it has four rests", "it has exactly one rest", "each pair is a rest"], "why": "The no-rest technique."}, {"q": "The newcomer stays out, the firm would fight. Why is it a rest yet suspect?", "a": "the firm would not really fight if the newcomer came in", "w": ["the newcomer gains by staying out", "the firm gains by fighting", "it is not a rest"], "why": "The empty-threat technique."}, {"q": "A rest where no player gains by changing alone. Its accepted name?", "a": "a Nash equilibrium", "w": ["a Pareto optimum", "a dominant strategy", "a minimax value"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞17"]=[{"q": "W ⊆ V ⊆ U and s an answer on U. What is cutting in two steps?", "a": "the same as cutting to W at once", "w": ["the empty answer", "a different answer", "not defined"], "why": "The two-cuts technique."}, {"q": "Answers on pieces that agree on every overlap. What does the gluing rule ask?", "a": "they come from exactly one answer on the whole", "w": ["they agree everywhere already", "they are constant", "they come from two answers"], "why": "The gluing rule."}, {"q": "Do continuous functions glue?", "a": "yes, to exactly one continuous function on the whole", "w": ["no, never", "only when there are two pieces", "only when each piece is constant"], "why": "The continuous-glue technique."}, {"q": "Do bounded functions glue?", "a": "no: agreeing pieces can have no bounded whole", "w": ["yes, always", "only on finite pieces", "only when continuous"], "why": "The bounded-fails technique."}, {"q": "Rung 41’s table of readings on two photons agrees on every overlap. What is missing?", "a": "a joint answer", "w": ["any reading", "an overlap", "a table"], "why": "The no-joint technique."}, {"q": "When can a plan fit the steps round a loop?", "a": "only when the product of the signs round the loop is +1", "w": ["always", "only when every sign is −1", "when the loop has three steps"], "why": "The loop-sign technique."}, {"q": "The limit on a plan of answers in rung 41, said here as what?", "a": "a failure to glue", "w": ["a failure to cut", "a gluing that always works", "a loop with sign +1"], "why": "Local answers that do not glue."}, {"q": "Data on pieces that glues. Its accepted name?", "a": "a sheaf", "w": ["a presheaf", "a bundle", "a cover"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞18"]=[{"q": "Rung 7’s two-stage world read as data. What carries each thing now?", "a": "a map to itself later", "w": ["a map back to an earlier stage", "a copy", "nothing"], "why": "Data over two stages."}, {"q": "How many parts has the data with one thing at each stage?", "a": "three", "w": ["two", "four", "one"], "why": "The three-parts technique."}, {"q": "At the middle value m, what does not-not give?", "a": "1", "w": ["m", "0", "not defined"], "why": "The middle-value technique."}, {"q": "So which principle fails at now in the two-stage world?", "a": "either-way, P ∨ ¬P", "w": ["P ⇒ P", "P ∧ P ⇒ P", "¬(P ∧ ¬P)"], "why": "Established later, not now."}, {"q": "When does “every x has P” hold at a stage?", "a": "when every x present at every later stage has P", "w": ["when some x has P at that stage", "when the x present now have P", "never, in a two-stage world"], "why": "The look-ahead technique."}, {"q": "A statement false at a stage of a world where all the techniques used are true. What follows?", "a": "it has no proof by those techniques", "w": ["it is true", "it is proved", "the world is two-valued"], "why": "The settling-world technique."}, {"q": "When is the logic of every world of data over an order two-valued?", "a": "when no stage comes strictly after another", "w": ["when there are two stages", "when there is a last stage", "always"], "why": "The two-values technique."}, {"q": "The logic with three ordered values computed this way. Its accepted name?", "a": "a Heyting algebra", "w": ["a Boolean algebra", "a lattice of Kleene", "a de Morgan algebra"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞19"]=[{"q": "Rung 44: every finite algebra of and, or and not is the parts of which set?", "a": "the set of its atoms", "w": ["the set of its members", "the empty set", "the set of its questions"], "why": "Read here as ways of deciding."}, {"q": "In a finite algebra, the way h goes to which atom?", "a": "the one atom a with h(a) = 1", "w": ["every atom", "the largest member", "the bottom 0"], "why": "The atom-way technique."}, {"q": "A map of algebras becomes what between their spaces?", "a": "a function the other way", "w": ["a function the same way", "nothing", "a pair of functions"], "why": "Every arrow turned round."}, {"q": "The ways of deciding the finite-or-cofinite parts of ℕ: one for each n, and what else?", "a": "one more, “is the part cofinite?”", "w": ["none else", "two more", "one for each part"], "why": "The one-more-point technique."}, {"q": "How is the algebra read back from its space?", "a": "as the pieces both open and closed", "w": ["as the points", "as the open pieces only", "as the closed pieces only"], "why": "The clopen-back technique."}, {"q": "In an algebra whose members can be listed, what does every x ≠ 0 have?", "a": "a way of deciding with h(x) = 1", "w": ["an atom below it", "an undo", "a cofinite part"], "why": "The growth technique."}, {"q": "Rung 38’s finitely-many-suffice for statements is which result for this space?", "a": "rung 34’s finitely-many-suffice for a space", "w": ["the either-way principle", "the parallel rule", "the diagonal argument"], "why": "Logic as a space."}, {"q": "The space of ways of deciding. Its accepted name?", "a": "the Stone space", "w": ["the Zariski space", "the Cantor space", "the Hilbert space"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞20"]=[{"q": "A turning of a group is a map into the circle of size 1 that turns combining into what?", "a": "multiplying", "w": ["adding", "taking the larger", "doing nothing"], "why": "Turnings."}, {"q": "What are the turnings of a clock of N?", "a": "a clock of N", "w": ["the circle", "the whole numbers", "the line"], "why": "The clock-turnings technique."}, {"q": "What are the turnings of the whole numbers?", "a": "the circle", "w": ["the whole numbers", "a clock", "the line"], "why": "The whole-turnings technique."}, {"q": "What are the turnings of the line?", "a": "the line", "w": ["the circle", "a clock", "the whole numbers"], "why": "Each turning group, its own kind."}, {"q": "The turnings of G × H?", "a": "the products of a turning of G and a turning of H", "w": ["the turnings of G only", "the sums of the turnings of G and H", "none but the do-nothing"], "why": "The product-turnings technique."}, {"q": "Σ over g of χ(g), for χ not the do-nothing turning?", "a": "0", "w": ["|G|", "1", "−1"], "why": "The turning-sum technique."}, {"q": "The transform of the even mix over a coset x + H is nonzero where?", "a": "exactly at the turnings that are 1 on all of H", "w": ["everywhere", "only at the do-nothing turning", "nowhere"], "why": "The hidden-part technique."}, {"q": "The group of turnings of a group. Its accepted name?", "a": "the dual group, or Pontryagin dual", "w": ["the quotient group", "the automorphism group", "the free group"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞21"]=[{"q": "What is kept when the group is forgotten?", "a": "its representations, their maps, side by side, and the forgetful map", "w": ["only the number of its members", "only one representation of it", "the group table, without the group"], "why": "The ways it acts."}, {"q": "For the clock of 3, a choice uₖ with u₀ = 1 and uₖ₊ₗ = uₖ uₗ is what?", "a": "uₖ = zᵏ for a z with z³ = 1", "w": ["uₖ = k", "uₖ = 1 always", "uₖ = 3ᵏ"], "why": "The clock-back technique."}, {"q": "For the shuffles of three, what is W ⊗ W?", "a": "1 + ε + W", "w": ["W", "1 + W", "ε"], "why": "The shuffle-table technique."}, {"q": "And ε ⊗ ε?", "a": "1", "w": ["ε", "W", "0"], "why": "The shuffle-table technique."}, {"q": "Every family of grids that respects everything is ρ(g) for how many g?", "a": "exactly one", "w": ["none", "two", "every g"], "why": "The rebuild technique."}, {"q": "For a turn-about group, rebuilding is which earlier result?", "a": "∞20’s turnings of the turnings", "w": ["the fixed-point technique", "Bayes", "the pentagon rule"], "why": "The double turning."}, {"q": "Why does the forgetful map matter?", "a": "two different groups of eight members have the same table", "w": ["without it no table exists", "it adds members", "it makes the group finite"], "why": "The same-table technique."}, {"q": "Rebuilding a group from its representations. Its accepted name?", "a": "Tannaka–Krein duality", "w": ["Pontryagin duality", "Stone duality", "Galois theory"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞22"]=[{"q": "Lifting a loop once round, what happens to the points over the base point?", "a": "each moves to another: a shift", "w": ["they stay put", "they merge", "they vanish"], "why": "The shift technique."}, {"q": "When is a covering connected?", "a": "when the shift reaches every point from any one", "w": ["when it has one point", "always", "when the shift does nothing"], "why": "Coverings as sets with a shift."}, {"q": "The placements of E in K: how many orbits does G have on them?", "a": "one, of size [E : ℚ]", "w": ["one for each placement", "none", "two"], "why": "The placement technique."}, {"q": "A set with one orbit is matched with what?", "a": "the classes gH, H fixing a point", "w": ["the members of H", "the whole of G", "the empty set"], "why": "The one-orbit technique."}, {"q": "The symmetries of the forgetful map on sets with a G-action are exactly what?", "a": "the members of G", "w": ["the part-groups", "the orbits", "the points"], "why": "The read-off technique."}, {"q": "The flip a + bi ↦ a − bi, for x³ − 2. Which member of its group is it?", "a": "the swap (2 3)", "w": ["the turn (1 2 3)", "the do-nothing", "the swap (1 2)"], "why": "The mirror-loop technique."}, {"q": "Connected pieces are matched with what in each case?", "a": "part-groups", "w": ["points", "orbits of size 1", "fields of size 2"], "why": "The shared shape."}, {"q": "A category of sums of connected pieces with a point-counting map. Its accepted name?", "a": "a Galois category", "w": ["an abelian category", "a topos of sets", "a groupoid"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞23"]=[{"q": "In an exact row, what is each map’s reach?", "a": "the next map’s loss", "w": ["the next map’s reach", "empty", "the whole of the next group"], "why": "Exact rows."}, {"q": "0 → A → B → C → 0 is exact, all finite. What is |B|?", "a": "|A| · |C|", "w": ["|A| + |C|", "|C| − |A|", "|A|"], "why": "The short-row technique."}, {"q": "The snake map δ goes from what to what?", "a": "from what γ loses to what α leaves unreached", "w": ["from A to C", "from B back to B", "from what α loses to what γ loses"], "why": "The snake technique, found by chasing members."}, {"q": "What is ℤ/4 ⊗ ℤ/6?", "a": "a clock of 2", "w": ["a clock of 24", "a clock of 12", "0"], "why": "The clock-loss technique: a clock of the greatest common divisor."}, {"q": "How many stacks of ℤ/2 on ℤ/2 are there?", "a": "two: the clock of 4 and ℤ/2 × ℤ/2", "w": ["one", "four", "none"], "why": "The two-stacks technique."}, {"q": "Which of those two stacks does not split?", "a": "the clock of 4", "w": ["ℤ/2 × ℤ/2", "both", "neither"], "why": "The two-stacks technique."}, {"q": "Doubling ℤ, then taking the remainder mod 2. Does that stack split?", "a": "no", "w": ["yes", "only for even numbers", "only in ℤ/4"], "why": "The no-split technique."}, {"q": "The part lost by tensoring. Its accepted name?", "a": "Tor", "w": ["Ext", "the cokernel", "the image"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞24"]=[{"q": "What are the points of a ring here?", "a": "its prime parts", "w": ["its members", "its units", "its zero divisors"], "why": "The points of ℤ."}, {"q": "At which points of ℤ does 12 vanish?", "a": "at (2) and (3)", "w": ["at (12) only", "at every point", "at (0)"], "why": "The vanish technique."}, {"q": "What vanishes at the point (0) of ℤ?", "a": "only 0", "w": ["every number", "every prime", "1"], "why": "The vanish technique."}, {"q": "Why is the union of two closed sets closed?", "a": "V(I) ∪ V(J) = V(IJ)", "w": ["V(I) ∪ V(J) = V(I + J)", "it is always the whole space", "closed sets never meet"], "why": "The closed-union technique."}, {"q": "In the polynomials over ℝ, (x² + 1) is one point. What does it stand for?", "a": "the pair i, −i", "w": ["the number 1", "the number −1", "no number"], "why": "The paired-point technique."}, {"q": "How many points of ℤ[ω] lie over (3)?", "a": "two", "w": ["one", "three", "none"], "why": "The lying-over technique."}, {"q": "The ring maps from A to a ring R match what?", "a": "the solutions of a² + b² = 1 in R", "w": ["the members of R", "the primes of R", "the units of A"], "why": "The points-are-solutions technique."}, {"q": "The space of prime parts of a ring. Its accepted name?", "a": "the spectrum, Spec R", "w": ["the Stone space", "the dual group", "the projective line"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞25"]=[{"q": "A surface with rims goes to what?", "a": "a straight map from its incoming rims’ space to its outgoing rims’", "w": ["a single circle, its outer rim", "a set of points, one per rim", "a group, its loops"], "why": "Surfaces as arrows."}, {"q": "A closed surface has no rims. What does it go to?", "a": "a number", "w": ["a circle", "a space of vectors", "nothing"], "why": "No rims in, none out."}, {"q": "Gluing two surfaces along whole circles. What happens to their counts χ?", "a": "they add", "w": ["they multiply", "the larger wins", "they cancel"], "why": "The glued-count technique."}, {"q": "How many pieces does a sphere with g handles cut into?", "a": "2g + 2", "w": ["g", "4g", "g + 1"], "why": "The four-pieces technique."}, {"q": "Which shapes fix the whole rule, each read both ways?", "a": "a disc and a pair of trousers", "w": ["a sphere and a doughnut", "a circle alone", "a cylinder"], "why": "Four kinds of piece."}, {"q": "With the small choice of space, what does a sphere with g handles go to?", "a": "2ᵍ", "w": ["2g", "g²", "1"], "why": "The genus-count technique."}, {"q": "For every rule of this kind, what does the doughnut go to?", "a": "dim A", "w": ["0", "1", "2"], "why": "The doughnut technique, as ∞12’s loop was n."}, {"q": "Such a rule from surfaces to spaces of vectors. Its accepted name?", "a": "a two-dimensional topological quantum field theory", "w": ["a sheaf on the surfaces", "a Frobenius manifold", "a cobordism group of surfaces"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞26"]=[{"q": "How many levels does rung 47’s natural map make?", "a": "three: things, arrows, arrows between arrows", "w": ["two: things and arrows", "one: things", "four"], "why": "Arrows between arrows."}, {"q": "In how many ways do arrows between arrows run in a row?", "a": "two: along and across", "w": ["one", "three", "none"], "why": "Along and across."}, {"q": "(β′ ∘ β) ∗ (α′ ∘ α) equals what?", "a": "(β′ ∗ α′) ∘ (β ∗ α)", "w": ["(β ∗ α′) ∘ (β′ ∗ α)", "β ∘ α", "α ∗ β"], "why": "The interchange technique."}, {"q": "Two ways of combining share a do-nothing and obey interchange. What follows?", "a": "they are the same way, and it turns about", "w": ["they differ", "neither turns about", "only one has a do-nothing"], "why": "The two-become-one technique."}, {"q": "Which loop group of a space always turns about?", "a": "the second", "w": ["the first", "neither", "only the first of a circle"], "why": "The second-loops technique."}, {"q": "Must rung 34’s first loop group turn about?", "a": "no", "w": ["yes", "only for spheres", "only for finite spaces"], "why": "Only from the second level up."}, {"q": "Which of ∞11’s rules was the first of the tower’s rules?", "a": "the pentagon", "w": ["the triangle", "the snake", "the square"], "why": "Levels without end."}, {"q": "The two-become-one technique. Its accepted name?", "a": "the Eckmann–Hilton argument", "w": ["the Yoneda lemma", "the snake lemma", "the Whitehead lemma"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞27"]=[{"q": "The run H, a turn by φ, H, from |0⟩. With what chance does it read 1?", "a": "sin²(φ/2)", "w": ["cos²(φ/2)", "φ/2π", "sin φ"], "why": "Roads that cancel: parts add before they are squared."}, {"q": "m qubits together. What is the dimension of their joint space?", "a": "2ᵐ", "w": ["2m", "m²", "m"], "why": "A product of m copies of ℂ²."}, {"q": "H on each of m qubits, from |0⋯0⟩. What comes out?", "a": "the even spread over all 2ᵐ basis states", "w": ["|1⋯1⟩", "|0⋯0⟩ again", "a single random basis state"], "why": "The register-size technique."}, {"q": "A register evenly spread over x₀ + jr, r dividing Q, then the turning transform. Which readings can come out?", "a": "whole multiples of Q/r", "w": ["whole multiples of r", "only 0", "every k equally"], "why": "The turning transform finds a period."}, {"q": "Roughly how many gates does the turning transform take on m qubits?", "a": "about m²/2", "w": ["about 2ᵐ", "about m", "about m!"], "why": "One H and l − 1 turnings on each qubit."}, {"q": "When r does not divide Q, how is c/r read off the reading k?", "a": "as a convergent of the staircase of k/Q, once Q ≥ N²", "w": ["as k divided by r", "by rounding k to a multiple of r", "it cannot be read"], "why": "The nearest-peak technique."}, {"q": "A run factors N with a few repeats. What does each run cost, about?", "a": "n³ gates, mostly computing bˣ", "w": ["2ⁿ gates", "n gates", "one gate per digit of N"], "why": "The whole of it, counted."}, {"q": "The turning transform on qubits. Its accepted name?", "a": "the quantum Fourier transform", "w": ["the Walsh–Hadamard transform", "the Rabi transform", "the phase gate"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞28"]=[{"q": "A qubit driven on its own frequency. What is the chance of 1 after time t?", "a": "sin²(Ωt/2)", "w": ["cos(Ωt)", "Ωt/2", "e^(−Ωt)"], "why": "Driven at its own frequency, it swings."}, {"q": "Driven off frequency by Δ. What ceiling does the chance of 1 never pass?", "a": "Ω²/(Ω² + Δ²)", "w": ["Δ²/(Ω² + Δ²)", "½", "1"], "why": "Off frequency the swing is shallow."}, {"q": "N random turnings of ±ε. How does the average of e^(iθ) fade?", "a": "as (cos ε)ᴺ, about e^(−Nε²/2)", "w": ["as 1/N", "as ε·N", "it does not fade"], "why": "Noise as a small random turning."}, {"q": "Can one gate copy every state of a qubit?", "a": "no: only states equal or at right angles", "w": ["yes, with enough qubits", "yes, if it is slow", "only the state |0⟩"], "why": "No copying."}, {"q": "u|000⟩ + v|111⟩, and two readings: do 1 and 2 agree, do 2 and 3 agree. What do they find?", "a": "which qubit flipped, leaving u and v alone", "w": ["the values of u and v", "whether all three flipped", "nothing about the flip"], "why": "Three qubits against one flip."}, {"q": "d = 2t − 1 qubits, each flipping with chance p. When can the majority’s failure be made as small as wished?", "a": "when p < ¼, by making d larger", "w": ["for any p, with d = 3", "only when p = 0", "when p > ½"], "why": "A threshold."}, {"q": "The grid code below threshold. What does each step from d to d + 2 do to the failure?", "a": "divides it by Λ = p*/p", "w": ["doubles it", "adds p to it", "leaves it alone"], "why": "The grid code."}, {"q": "The swing of a driven qubit. Its accepted name?", "a": "Rabi oscillation", "w": ["Ramsey fringes", "dephasing", "Shor’s swing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞29"]=[{"q": "A fixed word of k letters in a random string with W starting places. How often is it expected?", "a": "W/4ᵏ times", "w": ["W · 4ᵏ times", "k/W times", "once, always"], "why": "Three billion letters, read both ways."}, {"q": "A 20-letter word in a genome of 3 × 10⁹ letters, both strands. About how often by chance?", "a": "about 0.0055 times", "w": ["about 55 times", "about once", "about 6 × 10⁹ times"], "why": "6 × 10⁹ / 4²⁰."}, {"q": "A full test is made only where a signal appears, with chance q. What happens to the chance matches?", "a": "they are multiplied by q", "w": ["they are divided by q", "they are unchanged", "they vanish"], "why": "A short signal first."}, {"q": "How many words of k letters differ from a given one in exactly j places?", "a": "C(k, j) · 3ʲ", "w": ["kʲ", "4ʲ", "C(k, j)"], "why": "Near matches."}, {"q": "X is a sum of independent 0-or-1 counts with mean μ. A bound on P(X ≥ t) for t > μ?", "a": "e^(−μ)(eμ/t)ᵗ", "w": ["μ/t", "e^(−t)", "t/μ"], "why": "How far the count can stray."}, {"q": "A virus escapes each of m stored stretches with chance q, independently. Chance it escapes all?", "a": "qᵐ", "w": ["mq", "q/m", "1 − qᵐ"], "why": "A memory of past viruses."}, {"q": "The short signal beside the target. Its accepted name?", "a": "the PAM, protospacer adjacent motif", "w": ["the spacer", "the guide RNA", "the repeat"], "why": "The cellar."}, {"q": "The stored stretches in the CRISPR rows. Their accepted name?", "a": "spacers", "w": ["protospacers", "repeats", "guides"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞30"]=[{"q": "The 12 changes of one DNA letter into another fall into how many kinds of change of a letter pair?", "a": "6", "w": ["12", "4", "3"], "why": "One letter, two strands: each change read on the partner."}, {"q": "Target changed with chance p, each of k bystanders with chance b. Chance the target alone changes?", "a": "p(1 − b)ᵏ", "w": ["p · bᵏ", "p − kb", "(1 − p)bᵏ"], "why": "Did it change, and only there?"}, {"q": "n independent looks, none sees a thing. Which rates are ruled out at the 5% level?", "a": "any above 3/n", "w": ["any above 1/n", "any above 3n", "none"], "why": "Counting what is rare."}, {"q": "A cost C a year for ever, discounted at rate r. Worth today?", "a": "C/r", "w": ["C · r", "C/(1 + r)", "C"], "why": "The first approved treatment."}, {"q": "Each of two copies changed with chance p, independently. Chance exactly one is changed?", "a": "2p(1 − p)", "w": ["p²", "p(1 − p)", "1 − p²"], "why": "Twins, 2018."}, {"q": "Two children per carrier, each inheriting with chance ½. What happens to the carrier line, in the long run?", "a": "it dies out with chance 1, though the mean stays 1", "w": ["it grows without bound", "it stays at exactly one carrier", "it doubles each generation"], "why": "Edits that pass down."}, {"q": "Editors that change one letter without cutting both strands. Their accepted name?", "a": "base editors", "w": ["prime editors", "nickases", "guide RNAs"], "why": "The cellar."}, {"q": "Cas9 with one of its two cutting sites disabled. Its accepted name?", "a": "a nickase", "w": ["a base editor", "a PAM", "a spacer"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞31"]=[{"q": "Atoms of mass m on springs κ, spacing a. The turn rate of a wave of number k?", "a": "2√(κ/m) |sin(ka/2)|", "w": ["√(κ/m) · ka", "κ/m", "2√(κ/m)"], "why": "Atoms on springs."}, {"q": "What is the shortest wave a lattice of spacing a can carry?", "a": "2a", "w": ["a", "a/2", "none: any length"], "why": "The shortest wave."}, {"q": "Long waves on a lattice. How fast do they run?", "a": "at v = a√(κ/m), whatever their length", "w": ["slower the longer they are", "at the speed of light", "not at all"], "why": "The speed of sound."}, {"q": "A lattice wave of turn rate ω at temperature T holds how many steps on average?", "a": "1/(e^(ħω/kT) − 1)", "w": ["kT/ħω exactly", "e^(−ħω/kT)", "½"], "why": "A wave takes energy in steps."}, {"q": "Far below θ, how does a crystal’s heat capacity go with T?", "a": "as T³", "w": ["as T", "as e^(−θ/T)", "it stays at 3Nk"], "why": "The cube law."}, {"q": "Far above θ, what is the heat capacity of N atoms?", "a": "3Nk", "w": ["Nk", "0", "9NkT"], "why": "The 3R rule."}, {"q": "The 3R rule. Its accepted name?", "a": "the law of Dulong and Petit", "w": ["Debye’s law", "the Einstein model", "the Wiedemann–Franz law"], "why": "The cellar."}, {"q": "A step of energy of a lattice wave. Its accepted name?", "a": "a phonon", "w": ["a photon", "a magnon", "a Cooper pair"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞32"]=[{"q": "A current in a ring of resistance R and inductance L. How does it die?", "a": "as I₀e^(−Rt/L)", "w": ["as I₀/(1 + Rt)", "linearly, at rate R", "it never dies"], "why": "A ring that keeps its current."}, {"q": "Inside a body with no resistance, what does the magnetic field do?", "a": "it cannot change", "w": ["it is pushed out", "it doubles", "it falls to 0 at once"], "why": "Zero resistance freezes the field."}, {"q": "In a superconductor a field at the face dies inside as what?", "a": "B₀e^(−x/λ), with λ = √(m/(μ₀ne²))", "w": ["B₀/x", "B₀ cos(x/λ)", "it does not die"], "why": "The field is pushed out."}, {"q": "Freeing an electron from its pair costs Δ. What share is free at T?", "a": "about e^(−Δ/kT)", "w": ["Δ/kT", "½", "kT/Δ"], "why": "Electrons in pairs."}, {"q": "Pairs glued by lattice waves. How does T_c go with the atoms’ mass M?", "a": "as 1/√M", "w": ["as M", "as 1/M²", "it does not depend on M"], "why": "Light atoms, and a hard squeeze."}, {"q": "A step left after taking away a background proves a step in the sample only if…", "a": "the background was fixed before the signal was seen", "w": ["the signal was fixed before the background was seen", "the background was guessed after the signal", "nothing was fixed in advance"], "why": "How a claim is checked."}, {"q": "The push-out of the field from a superconductor. Its accepted name?", "a": "the Meissner effect", "w": ["the Josephson effect", "the Hall effect", "persistent current"], "why": "The cellar."}, {"q": "A body with zero resistance and nothing more. Its accepted name?", "a": "a perfect conductor", "w": ["a superconductor", "an insulator", "a semimetal"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞33"]=[{"q": "How many atoms does each cell of the honeycomb hold?", "a": "two", "w": ["one", "three", "six"], "why": "The honeycomb cell."}, {"q": "An electron hopping by t on the honeycomb. Its two levels for each wave k?", "a": "±t|1 + e^(ik·a₁) + e^(ik·a₂)|", "w": ["±t", "±t|k|²", "t cos(k·a₁)"], "why": "Three neighbours make two bands."}, {"q": "Where do the honeycomb’s two bands touch?", "a": "at corners of the six-sided pattern of waves", "w": ["at the middle of each atom’s ring", "along the straight edges of the sheet", "nowhere in the pattern"], "why": "Three turnings of length 1 add to 0."}, {"q": "Near each corner, how do the levels go with q?", "a": "E = ±ħv|q|: a cone with no mass", "w": ["E = ħ²q²/2m", "E = ±t", "E = 0"], "why": "A cone with no mass."}, {"q": "n extra electrons per unit area fill the cone to q_F. What is q_F²?", "a": "πn", "w": ["2πn", "n/π", "n²"], "why": "Pulled, and filled."}, {"q": "Two lattices of side a, one turned by θ. Side of the big pattern?", "a": "a/(2 sin(θ/2))", "w": ["a sin θ", "a/θ²", "2a"], "why": "Two sheets, turned."}, {"q": "The one-atom sheet of carbon in a honeycomb. Its accepted name?", "a": "graphene", "w": ["hexagonal boron nitride", "diamond", "graphite"], "why": "The cellar."}, {"q": "The pattern from two turned sheets. Its accepted name?", "a": "a moiré pattern", "w": ["a Brillouin zone", "a Dirac cone", "a sublattice"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞34"]=[{"q": "The prover sends t ≡ gʳ, the checker tosses c, the prover answers s ≡ r + cx. What does the checker test?", "a": "gˢ ≡ t · yᶜ", "w": ["gˢ ≡ t + yᶜ", "gˢ ≡ tᶜ · y", "s ≡ t · yᶜ"], "why": "A commitment, a coin, an answer."}, {"q": "A prover answers both coins, 0 and 1, for one t, with s₀ and s₁. What do the two answers give?", "a": "the secret, x ≡ s₁ − s₀ (mod p − 1)", "w": ["nothing at all", "the commitment r only", "x ≡ s₀ · s₁"], "why": "A cheat ready for one coin."}, {"q": "Twenty rounds with fresh fair coins. A cheat fools the checker with chance at most?", "a": "2⁻²⁰", "w": ["1/20", "½", "20 · 2⁻¹"], "why": "Rounds multiply."}, {"q": "Pick c and s at random, then put t ≡ gˢ y⁻ᶜ. What do these records show?", "a": "the chances of honest rounds: nothing is learned", "w": ["the secret x, one bit at a time", "a cheat, caught every time", "half the bits of the secret x"], "why": "A round written backwards."}, {"q": "What takes the place of the checker’s coin in a signature?", "a": "a fingerprint H(m, t)", "w": ["the signer’s secret x", "the message m alone", "a coin the signer tosses"], "why": "A fingerprint for a coin."}, {"q": "Knowing one of two secrets, the prover writes one round backwards and answers the coin c with c₁ ≡ c − c₂. What does the checker test?", "a": "c₁ + c₂ ≡ c, and both rounds", "w": ["c₁ = c₂", "only the real round", "c₁ · c₂ ≡ c"], "why": "One of two, and not which."}, {"q": "The round with a big coin. Its accepted name?", "a": "the Schnorr identification protocol", "w": ["the Diffie–Hellman exchange", "the RSA signature", "Shamir’s secret sharing"], "why": "The cellar."}, {"q": "Replacing the coin with a fingerprint. Its accepted name?", "a": "the Fiat–Shamir transform", "w": ["the random oracle", "the Chaum–Pedersen proof", "the simulator"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞35"]=[{"q": "Links the same both ways, no self-links, one unit changed at a time. What happens to the loop?", "a": "every change lowers the energy, so it comes to rest", "w": ["it cycles for ever", "the energy rises until it stops", "it rests only when N is even"], "why": "A loop that comes to rest."}, {"q": "Patterns ξ^μ written into links. What is wᵢⱼ?", "a": "(1/N) Σ ξᵢ^μ ξⱼ^μ", "w": ["Σ (ξᵢ^μ + ξⱼ^μ)", "ξᵢ^μ / ξⱼ^μ", "(1/N) Σ ξᵢ^μ"], "why": "Many patterns in one set of links."}, {"q": "p patterns, at right angles in pairs. Every one rests while?", "a": "p < N", "w": ["p < √N", "p < 0.138N", "p < N/2"], "why": "Many patterns in one set of links."}, {"q": "Random patterns of N signs. Near what count does recall break?", "a": "p ≈ 0.138N", "w": ["p ≈ N", "p ≈ √N", "p ≈ N/2"], "why": "How many random patterns fit."}, {"q": "The cue beats every other pattern’s overlap by at least g. The weight on the nearest pattern is at least?", "a": "1/(1 + (p − 1)e^(−βg))", "w": ["e^(−βg)", "1/p", "1 − e^(βg)"], "why": "A soft lookup."}, {"q": "A machine with n knobs is trained on D tokens. About how many multiplications and additions?", "a": "6nD", "w": ["2nD", "nD", "6n²D"], "why": "What a text machine is trained to do."}, {"q": "The loop with links the same both ways. Its accepted name?", "a": "a Hopfield network", "w": ["a perceptron", "a transformer", "a Boltzmann machine"], "why": "The cellar."}, {"q": "The soft lookup inside a text machine. Its accepted name?", "a": "attention", "w": ["convolution", "backpropagation", "dropout"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞36"]=[{"q": "What is a kind’s level in a food web?", "a": "one more than the average level of what it eats", "w": ["one more than the highest level of what it eats", "the number of kinds it eats", "one less than the average level of its eaters"], "why": "A web is a graph with arrows."}, {"q": "Near a rest, x′ ≈ Ax. When does the web hold?", "a": "when every stretch of A has real part below 0", "w": ["when every entry of A is below 0", "when A has no zeros", "when the diagonal sums to 0"], "why": "A pair, read as a grid."}, {"q": "The grid with −d on the diagonal and p, q off it. Its stretches?", "a": "−d ± √(pq)", "w": ["−d ± pq", "d ± √(p + q)", "−p and −q"], "why": "A pair, read as a grid."}, {"q": "A pair whose links p and q have one sign. It holds exactly while?", "a": "pq < d²", "w": ["pq > d²", "p + q < d", "at every strength"], "why": "A pair, read as a grid."}, {"q": "A pair whose links p and q have opposite signs, as eater and eaten. When does it hold?", "a": "at every strength", "w": ["only while pq < d²", "never", "only when p = −q"], "why": "A pair, read as a grid."}, {"q": "In every row, the diagonal entry is below 0 and outweighs the sizes of the others put together. What follows?", "a": "the rest holds, whatever the other signs", "w": ["the rest breaks", "the web has one level", "nothing, without the signs"], "why": "Strong crowding holds any web."}, {"q": "S kinds, linked with chance C, links of spread width σ. A random web holds while?", "a": "σ√(SC) < 1", "w": ["σSC < 1", "σ < √(SC)", "SC < σ"], "why": "A web drawn at random."}, {"q": "The rule σ√(SC) < 1. Its accepted name?", "a": "May’s stability criterion", "w": ["the Allesina–Tang criterion", "Gershgorin’s circle theorem", "the Lotka–Volterra rule"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞37"]=[{"q": "A machine in log room, on an input of length n. When does it stop?", "a": "within a power of n steps, or never", "w": ["within log n steps", "within 2ⁿ steps, always", "only on short inputs"], "why": "Room smaller than the input."}, {"q": "How does more room decide more?", "a": "by the diagonal, with a counter to catch loops", "w": ["by guessing", "by counting dots layer by layer", "by a list of not-and gates"], "why": "More room decides more."}, {"q": "Without guessing, a path from u to v in a graph of N dots is found in room about?", "a": "(log₂ N)²", "w": ["log₂ N", "N", "√N"], "why": "A path in squared room."}, {"q": "With guessing, the same path question needs room about?", "a": "log₂ N", "w": ["(log₂ N)²", "N", "1"], "why": "A path in squared room."}, {"q": "How does a guessing machine in log room certify that v is not reached?", "a": "it counts the dots reached, layer by layer", "w": ["it tries every path at once", "it guesses a path and fails", "it cannot certify a no"], "why": "A count certifies a no."}, {"q": "Evaluating a list of not-and gates. Which is true?", "a": "it is fast, and every fast set reduces to it in log room", "w": ["it needs a power of 2 steps", "it is decided in log room", "it is not fast"], "why": "Log room against fast."}, {"q": "Log room equals fast exactly when?", "a": "gate lists can be run in log room", "w": ["guessing adds nothing to room", "paths need squared room", "every set is fast"], "why": "Log room against fast."}, {"q": "The result that guessing log room can certify a no. Its accepted name?", "a": "the Immerman–Szelepcsényi theorem", "w": ["Savitch’s theorem", "Reingold’s theorem", "the space hierarchy theorem"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞38"]=[{"q": "A change of variables of determinant 1 carries one form to another. What do they share?", "a": "the numbers they reach and the discriminant", "w": ["only their first coefficient", "nothing in general", "their value at (1, 1)"], "why": "Forms, and changing the variables."}, {"q": "The discriminant of x² + 2y²?", "a": "−8", "w": ["8", "2", "−4"], "why": "Forms, and changing the variables."}, {"q": "A positive form is reduced when?", "a": "|q| ≤ p ≤ r", "w": ["p ≤ q ≤ r", "p = r", "q = 0"], "why": "Reduced forms, and how many."}, {"q": "An odd prime ℓ not dividing D is reached by some form of discriminant D exactly when?", "a": "D is a square on the clock of ℓ", "w": ["ℓ divides D", "ℓ ≡ 1 (mod 4)", "D is a whole square"], "why": "Which primes, on a clock."}, {"q": "An odd prime ℓ ≠ 5 is x² + 5y² exactly when?", "a": "ℓ ≡ 1 or 9 (mod 20)", "w": ["ℓ ≡ 3 or 7 (mod 20)", "ℓ ≡ 1 (mod 4)", "ℓ ≡ 1 (mod 5)"], "why": "Two kinds, and a clock that sorts them."}, {"q": "A prime ℓ ≠ 23 is x² + xy + 6y² exactly when?", "a": "x³ − x − 1 has three roots on the clock of ℓ", "w": ["ℓ ≡ 1 (mod 23)", "−23 is a square on the clock of ℓ", "x³ − x − 1 has no root there"], "why": "Three kinds, and no clock."}, {"q": "n² + n + 41 is prime for every n from 0 up to?", "a": "39", "w": ["40", "41", "100"], "why": "Class number one, and forty-one."}, {"q": "The last D with one class of forms?", "a": "−163", "w": ["−23", "−41", "−167"], "why": "Class number one, and forty-one."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞39"]=[{"q": "The slope X at doing nothing of a smooth path of turns of space. What is true of X?", "a": "Xᵀ = −X", "w": ["Xᵀ = X", "X² = I", "det X = 1"], "why": "The turns near nothing."}, {"q": "Such slopes X make a space of how many directions?", "a": "3", "w": ["9", "6", "1"], "why": "The turns near nothing."}, {"q": "Two small turns done and undone leave I + ε²[A, B] and smaller terms. What is [A, B]?", "a": "AB − BA", "w": ["AB + BA", "A − B", "ABA⁻¹"], "why": "What two small turns leave behind."}, {"q": "In SU(2), whose bracket matches the turns of space, what is e^(2πK_z)?", "a": "−I", "w": ["I", "0", "K_z"], "why": "The same bracket, a different group."}, {"q": "A whole piece where L_z stretches run j, j − 1, …, −j. Its dimension?", "a": "2j + 1", "w": ["j", "2j", "j + 1"], "why": "The sizes of the pieces."}, {"q": "In a field B, a level of turning ℓ splits how?", "a": "into 2ℓ + 1 levels, μ_B B apart", "w": ["into 2 levels", "into ℓ levels, B apart", "not at all"], "why": "A magnet splits a line."}, {"q": "The small turnings of SU(n) make a real space of dimension?", "a": "n² − 1", "w": ["n²", "n(n − 1)/2", "2n"], "why": "The groups of the forces."}, {"q": "The space of small turnings with its bracket. Its accepted name?", "a": "a Lie algebra", "w": ["a Lie group", "a Clifford algebra", "a Banach space"], "why": "The cellar."}];
