(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞42"]=[{"q": "A union-closed family holds a one-member set {i}. Then i is in?", "a": "at least half the sets", "w": ["every set", "at least a tenth of the sets", "at most half the sets"], "why": "Families closed under joining."}, {"q": "A and B picked at random from F. Why is the surprise of A ∪ B at most that of A?", "a": "A ∪ B is in F, of surprise at most log₂|F|", "w": ["A ∪ B is a bigger set than A", "A and B are always the same", "surprise always falls when sets join"], "why": "Proving that something exists by picking at random."}, {"q": "H(a₁, …, aₙ) member by member?", "a": "H(a₁) + H(a₂ | a₁) + ⋯ + H(aₙ | a₁, …, aₙ₋₁)", "w": ["H(a₁) · H(a₂) ⋯ H(aₙ)", "H(aₙ) alone", "H(a₁) + ⋯ + H(aₙ), always"], "why": "Surprise, one member at a time."}, {"q": "What does knowing more do to the surprise left?", "a": "never raises it: H(X | Y, W) ≤ H(X | Y)", "w": ["always lowers it", "never lowers it", "doubles it"], "why": "Surprise, one member at a time."}, {"q": "The proof gives: some member is in at least what share of the sets?", "a": "a tenth", "w": ["half", "a third", "a hundredth"], "why": "Some member is in a tenth of the sets."}, {"q": "The sharp form of the one-member inequality turns the tenth into?", "a": "(3 − √5)/2 ≈ 0.382", "w": ["½", "(√5 − 1)/2 ≈ 0.618", "⅓"], "why": "The golden share, and the wall."}, {"q": "Two independent copies, each member in with chance p. H(A ∪ B) < H(A) when?", "a": "(3 − √5)/2 < p ≤ ½", "w": ["p < 0.1", "p = ½ only", "never"], "why": "The golden share, and the wall."}, {"q": "The question whether some member is in half the sets. Its accepted name?", "a": "Frankl’s union-closed sets conjecture", "w": ["the Erdős–Ko–Rado theorem", "Sperner’s theorem", "the sunflower conjecture"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞43"]=[{"q": "Every red and blue colouring of 1, …, 325 holds?", "a": "a one-colour run of three", "w": ["a one-colour run of ten", "every pattern", "nothing sure"], "why": "A run of three in every colouring."}, {"q": "On the clock of M, how many maps turn plus into times?", "a": "M", "w": ["M − 1", "2M", "1"], "why": "Turnings on a clock."}, {"q": "Σ_r |ĝ(r)|² equals?", "a": "M Σ_x |g(x)|²", "w": ["Σ_x |g(x)|²", "M²", "|Σ_x g(x)|²"], "why": "Energy on a clock."}, {"q": "The count of runs of three in A, by turnings?", "a": "(1/M) Σ_r Â(r)² Â(−2r)", "w": ["Σ_r Â(r)³", "(1/M) Σ_r |Â(r)|²", "M Â(0)"], "why": "Counting runs of three by turnings."}, {"q": "A set of share δ with no run of three. Against some r ≠ 0 it is unbalanced by?", "a": "δ²N/12", "w": ["δN", "N/12", "δ³"], "why": "A large coefficient."}, {"q": "So on a run of length about δ√N its share rises by?", "a": "δ²/48", "w": ["δ", "δ/2", "1/48"], "why": "A denser piece, again and again."}, {"q": "Why must the denser-piece step stop?", "a": "repeated, the share would pass 1", "w": ["N runs out of primes", "the coefficients vanish", "it never stops"], "why": "A denser piece, again and again."}, {"q": "The claim of 1927 that a colouring holds runs of every length. Its accepted name?", "a": "van der Waerden’s theorem", "w": ["Szemerédi’s theorem", "Parseval’s identity", "the Green–Tao theorem"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞44"]=[{"q": "A nonzero polynomial of degree d in n variables over a field of q members. At most how many zeros?", "a": "d qⁿ⁻¹", "w": ["qⁿ", "dⁿ", "d + q"], "why": "Few zeros in many variables."}, {"q": "Fewer than C(n + d, n) points. What can always be found?", "a": "a nonzero polynomial of degree d zero on all", "w": ["a line through all of them", "a point outside every line", "nothing in general"], "why": "Few zeros in many variables."}, {"q": "A set holding a line in every direction in Fⁿ has at least?", "a": "C(q + n − 1, n) ≥ qⁿ/n! points", "w": ["q points", "qⁿ points", "n! points"], "why": "A line in every direction."}, {"q": "Three different points of (ℤ/3)ⁿ make a line exactly when?", "a": "x + y + z = 0", "w": ["x = y", "x + y = z", "xyz = 0"], "why": "Caps on the clock of three."}, {"q": "In a cap, x + y + z = 0 forces?", "a": "x = y = z", "w": ["x = 0", "a line", "x + y = 0"], "why": "Caps on the clock of three."}, {"q": "A diagonal on A, nonzero at every x. Its slice rank?", "a": "|A|", "w": ["1", "0", "|A|²"], "why": "A diagonal cannot be thin."}, {"q": "A cap in (ℤ/3)ⁿ has at most how many points?", "a": "3 · 2.756ⁿ", "w": ["3ⁿ/n", "2ⁿ", "3ⁿ⁻¹"], "why": "The cap bound."}, {"q": "N lines in space have at most how many joints?", "a": "7N^(3/2)", "w": ["N²", "7N", "N³"], "why": "Joints, and distances in the plane."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞45"]=[{"q": "Sensitivity s(f) against block sensitivity bs(f). Which always holds?", "a": "s(f) ≤ bs(f)", "w": ["bs(f) ≤ s(f)", "s(f) = bs(f)", "s(f) · bs(f) = n"], "why": "Sensitive corners."}, {"q": "F takes only the values 1 and −1 on the cube. What do the squares F̂(S)² add to?", "a": "1", "w": ["2ⁿ", "0", "n"], "why": "Turnings on the cube."}, {"q": "The degree of a table f is?", "a": "the largest set S with a nonzero coefficient F̂(S)", "w": ["the number of inputs", "the number of corners where f is 1", "the largest sensitivity"], "why": "Turnings on the cube."}, {"q": "If deg f = d, what is found in a d-cube?", "a": "over half its corners, each with at most s(f) inner neighbours", "w": ["one corner joined to all d others", "exactly half the corners, none joined", "no corner with any neighbour"], "why": "The 1992 question, turned into corners."}, {"q": "The signed grid Aₙ on the cube’s edges. What is Aₙ²?", "a": "nI", "w": ["I", "0", "n²I"], "why": "A signed grid on the cube."}, {"q": "Every set of more than 2ⁿ⁻¹ corners of the n-cube holds a corner joined to at least how many others of the set?", "a": "√n", "w": ["n", "1", "n/2"], "why": "More than half the corners."}, {"q": "So sensitivity and degree are tied how?", "a": "s(f) ≥ √(deg f)", "w": ["s(f) ≥ deg f", "s(f) ≤ log(deg f)", "they are not tied"], "why": "More than half the corners."}, {"q": "The cube as a graph. Its accepted name?", "a": "the hypercube", "w": ["the Petersen graph", "the complete graph", "a tree"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞46"]=[{"q": "What area does the triangle with three equal sides and height 1 have?", "a": "1/√3 ≈ 0.577", "w": ["½", "1", "√3/4 ≈ 0.433"], "why": "Needles in every direction."}, {"q": "What does that triangle hold?", "a": "a segment of length 1 in every direction", "w": ["a disc of radius 1", "every triangle of height 1", "no segment of length 1"], "why": "Needles in every direction."}, {"q": "Slices slid together, k rounds with ratio α. The pile’s area is at most?", "a": "(α²ᵏ + 4(1 − α)/(1 + α)) times the triangle’s", "w": ["αᵏ times the triangle’s", "the triangle’s, unchanged", "2ᵏ times the triangle’s"], "why": "A tree of triangles."}, {"q": "Can a closed, bounded set of area 0 hold a unit segment in every direction?", "a": "yes", "w": ["no", "only in space", "only if it is a disc"], "why": "Size zero."}, {"q": "Such a set in the plane. Its dimension?", "a": "2", "w": ["1", "0", "1.5"], "why": "Dimension two in the plane."}, {"q": "The points within δ of such a set have area at least?", "a": "1/(3 + ln(1/δ))", "w": ["δ", "δ²", "1/√3"], "why": "Dimension two in the plane."}, {"q": "A set in space holding a unit segment in every direction has dimension at least?", "a": "2", "w": ["3", "1", "0"], "why": "In space."}, {"q": "A set holding a needle in every direction. Its accepted name?", "a": "a Kakeya set", "w": ["a Cantor set", "a Julia set", "a Vitali set"], "why": "The cellar."}];
