(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞49"]=[{"q": "A tiling kept by two slides in different directions. Its slides form?", "a": "a lattice ℤu + ℤv", "w": ["one line", "a circle", "nothing in general"], "why": "A repeat has a lattice."}, {"q": "If every set that tiles also tiled with a lattice, what would follow?", "a": "a machine could decide tiling, by two searches", "w": ["no set would tile", "every set would tile", "tiling would be random"], "why": "Square tiles with coloured edges."}, {"q": "Does any machine decide whether a set of square tiles covers the plane?", "a": "no: tiles can mimic any machine", "w": ["yes, always, by searching", "yes, for coloured tiles only", "only when there is one tile"], "why": "No machine decides tiling."}, {"q": "Kites and darts under substitution: (k, d) goes to?", "a": "(2k + d, k + d)", "w": ["(k + d, d)", "(2k, 2d)", "(d, k)"], "why": "Kites and darts."}, {"q": "What do kites : darts tend to, and why does it rule out a lattice?", "a": "φ, which is not a fraction", "w": ["2, a whole number", "1, by symmetry", "0, so darts vanish"], "why": "Kites and darts."}, {"q": "The hat is made of how many kites?", "a": "8", "w": ["6", "4", "12"], "why": "The hat."}, {"q": "What does the spectre need that the hat does not?", "a": "no flipped copies", "w": ["a second shape", "a lattice of slides", "coloured edges"], "why": "The spectre."}, {"q": "A single tile that tiles only without repeating. Its accepted name?", "a": "an einstein", "w": ["a Wang tile", "a Penrose rhombus", "a polyomino"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞50"]=[{"q": "The half disc of radius 1 in a hallway of width 1. Does it turn the corner?", "a": "yes", "w": ["no", "only if cut in two", "only with r = 2/π"], "why": "A hallway and a shape."}, {"q": "Two quarter discs set 2r apart, a half disc of radius r removed. Its area?", "a": "π/2 + 2r − πr²/2", "w": ["π/2 + πr²", "2r", "π − r²"], "why": "Two quarter discs and a bite."}, {"q": "That area is largest at what r?", "a": "r = 2/π", "w": ["r = 1", "r = ½", "r = π/4"], "why": "Two quarter discs and a bite."}, {"q": "The largest area of that family?", "a": "π/2 + 2/π ≈ 2.2074", "w": ["π/2 ≈ 1.571", "2√2 ≈ 2.83", "2.37"], "why": "Two quarter discs and a bite."}, {"q": "At the moment a sofa has turned by π/4, it lies in what?", "a": "two strips that cross at 45°", "w": ["one strip", "a quarter disc", "the corner square"], "why": "A ceiling from one moment."}, {"q": "So every sofa has area at most?", "a": "2√2 ≈ 2.83", "w": ["π/2", "2.2074", "4"], "why": "A ceiling from one moment."}, {"q": "The shape of 18 pieces has area about?", "a": "2.21953", "w": ["2.2074", "2.37", "2.83"], "why": "Eighteen pieces."}, {"q": "The question of the largest sofa. Its accepted name?", "a": "the moving sofa problem", "w": ["the Kakeya needle problem", "the piano movers’ problem", "the Kepler conjecture"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞51"]=[{"q": "A drum’s shape u with Δu = −k²u inside and u = 0 on the rim. Its pitch?", "a": "ck/2π", "w": ["ck", "k²/2π", "c/k"], "why": "Can you hear the shape of a drum?"}, {"q": "The numbers k² of the rectangle L × W?", "a": "π²(m²/L² + n²/W²) for whole m, n ≥ 1", "w": ["π(m/L + n/W)", "m² + n²", "π²mn/(LW)"], "why": "The pitches of a rectangle."}, {"q": "For any drum, the count N(K) of numbers up to K² is about?", "a": "(area)K²/(4π) − (rim)K/(4π)", "w": ["(rim)K", "(area)K", "K²"], "why": "What every drum lets you hear."}, {"q": "So what does the ear hear of every drum?", "a": "its area and its rim", "w": ["its whole shape", "its corners only", "nothing"], "why": "What every drum lets you hear."}, {"q": "A drum with exactly the numbers of a disc of radius ρ. What is it?", "a": "that disc", "w": ["any shape of that area", "a square", "it cannot be told"], "why": "What every drum lets you hear."}, {"q": "Two drums glued from seven right triangles share area 3.5, rim 6 + 3√2 and every pitch. Are they one shape?", "a": "no: same pitches, different shapes", "w": ["yes, always", "yes, turned over", "they share no pitch"], "why": "Seven triangles, glued two ways."}, {"q": "The carrying grid T has det T = −24. What does that give?", "a": "T can be undone, so every number matches", "w": ["the drums differ in area", "the drums have 24 pitches", "nothing about the numbers"], "why": "Carrying a shape across."}, {"q": "Drums with the same list of numbers. Their accepted name?", "a": "isospectral", "w": ["isoperimetric", "isometric", "congruent"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞52"]=[{"q": "Piles μ and holes ν. Which plan always exists?", "a": "π(x, y) = μ(x)ν(y)/m, the shared plan", "w": ["a map from piles to holes", "none in general", "the plan in order"], "why": "Grains or shares."}, {"q": "Prices with φ(x) + ψ(y) ≤ c(x, y). What do they give?", "a": "Σ φμ + Σ ψν ≤ the cost of every plan", "w": ["the cost of the best plan, always", "an upper bound on cost", "nothing"], "why": "A price at every place."}, {"q": "A plan and prices give equal totals. What follows?", "a": "both are best", "w": ["the plan is worst", "the prices are wrong", "nothing"], "why": "A price at every place."}, {"q": "On a line, with c a bending-up function of x − y. The cheapest matching?", "a": "match in order, x₁ to y₁ up to xₙ to yₙ", "w": ["match in reverse order", "match at random", "match to the nearest hole"], "why": "On a line, fill in order."}, {"q": "For squared distance, a matching T is cheapest exactly when?", "a": "Σ x · T(x) is largest", "w": ["Σ |x − T(x)| is largest", "T is the identity", "Σ x · T(x) is smallest"], "why": "The bowl behind the map."}, {"q": "Smooth piles, squared distance. The cheapest plan is?", "a": "a map, the uphill vector ∇u of a bowl", "w": ["a shared plan", "not unique", "a straight slide"], "why": "The bowl behind the map."}, {"q": "On a line, with c = |x − y|, the least cost per grain equals?", "a": "∫|F − G|, the area between the running totals", "w": ["the largest gap", "|mean of x − mean of y|²", "F(0) − G(0)"], "why": "A distance between piles."}, {"q": "One grain at 0 against one grain at θ ≠ 0. The surprise gap is 1 bit. The sand distance?", "a": "|θ|", "w": ["1", "0", "θ²"], "why": "Training machines that draw."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞53"]=[{"q": "For a symmetric grid A, what is tr Aᵏ?", "a": "λ₁ᵏ + ⋯ + λₙᵏ", "w": ["(λ₁ + ⋯ + λₙ)ᵏ", "λ₁ ⋯ λₙ", "k tr A"], "why": "A grid of coin tosses."}, {"q": "Which closed walks survive the average of tr Aᵏ?", "a": "those using every link at least twice", "w": ["every closed walk", "those using every link once", "those of odd length"], "why": "Walks that come home."}, {"q": "A closed walk of 2m steps visits m + 1 dots only when?", "a": "its links form a tree, each walked twice", "w": ["it is a single cycle", "it never repeats a link", "m is an even number"], "why": "Walks that come home."}, {"q": "The count Cₘ of such trees?", "a": "(2m choose m)/(m + 1)", "w": ["2ᵐ", "m!", "(2m choose m)"], "why": "Counting the trees."}, {"q": "C₃?", "a": "5", "w": ["6", "14", "20"], "why": "Counting the trees."}, {"q": "The half disc s(x)?", "a": "√(4 − x²)/(2π) on [−2, 2]", "w": ["e^(−x²/2)/√(2π)", "1/4 on [−2, 2]", "√(1 − x²)"], "why": "The half disc."}, {"q": "The stretches of a large coin grid, shrunk by √n, spread how?", "a": "as the half disc, whatever the coin", "w": ["as a bell", "evenly on [−1, 1]", "as the coin does"], "why": "The half disc."}, {"q": "For the small grid, the chance of a gap below ε is at most?", "a": "ε²/4", "w": ["ε", "ε/4", "½"], "why": "Gaps that push apart."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞54"]=[{"q": "Steps of width h every τ seconds. The spread stays finite and above 0 as τ shrinks exactly when?", "a": "h² is a fixed multiple of τ", "w": ["h is fixed", "h = τ", "h² = τ²"], "why": "Shrink and speed up."}, {"q": "The limit path W(t) is?", "a": "a bell of spread t", "w": ["a bell of spread t²", "fixed at 0", "even on [0, t]"], "why": "Shrink and speed up."}, {"q": "W(s) = x and W(t) = y. What is W at (s + t)/2?", "a": "(x + y)/2 plus a bell of spread (t − s)/4", "w": ["(x + y)/2 exactly, no bell", "x, the earlier value", "a bell of spread t about 0"], "why": "A path built from midpoints."}, {"q": "For a time t named in advance, the chance that W has a slope at t?", "a": "0", "w": ["1", "½", "it depends on t"], "why": "Continuous, a slope nowhere."}, {"q": "The spreading bell, step by step, obeys which rule in the limit?", "a": "u_t = ½u_xx", "w": ["u_t = u_x", "u_tt = u_xx", "u_t = 0"], "why": "The spreading bell, step by step."}, {"q": "The chance h of leaving a region through part of its edge. At each inside point it is?", "a": "the average of its four neighbours", "w": ["the largest of its neighbours", "1", "0"], "why": "Exit chances average their neighbours."}, {"q": "f has a complex slope. Δ(h ∘ f) equals?", "a": "|f′|² (Δh) ∘ f", "w": ["Δh", "f′ Δh", "0, always"], "why": "Angle-keeping maps carry the walk."}, {"q": "Fair coins on the rhombus board. The chance of a red crossing?", "a": "exactly ½", "w": ["about ⅓", "1", "0"], "why": "Crossings on a board of coins."}];
