(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞59"]=[{"q": "T(n) for odd n?", "a": "(3n + 1)/2", "w": ["3n + 1", "n/2", "(n + 1)/2"], "why": "The rule on a clock."}, {"q": "The first k parities of the run from n depend only on?", "a": "n mod 2ᵏ", "w": ["n mod 3ᵏ", "the size of n", "n mod k"], "why": "The parity code."}, {"q": "How many hours of the clock of 2ᵏ give each parity code?", "a": "exactly one", "w": ["two", "none, for some codes", "k"], "why": "The parity code."}, {"q": "A start chosen at random among the hours of 2ᵏ. Its k parities are?", "a": "k fair coin flips, independent", "w": ["all odd", "alternating", "fixed by k"], "why": "The parity code."}, {"q": "A code has m odd steps with 3ᵐ < 2ᵏ. For large n with that hour?", "a": "some step falls below n", "w": ["the run grows for ever", "the run is a circle", "n is odd"], "why": "Most numbers dip."}, {"q": "A circle of k steps, m odd, least member x. What must hold?", "a": "0 < k ln 2 − m ln 3 < m/(3x)", "w": ["k = m", "k ln 2 = m ln 3", "x < m"], "why": "A circle must be long."}, {"q": "The list 5/2, 5/3 takes 2ˣ 3ʸ to?", "a": "5ˣ⁺ʸ", "w": ["5ˣʸ", "2ʸ 3ˣ", "6ˣ⁺ʸ"], "why": "Cousins no machine can decide."}, {"q": "The question whether every number falls to 1. Its accepted name?", "a": "the Collatz conjecture", "w": ["the Goldbach conjecture", "the twin prime conjecture", "the abc conjecture"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞60"]=[{"q": "When is n perfect?", "a": "when σ(n) = 2n", "w": ["when σ(n) = n", "when σ(n) > 2n", "when n is prime"], "why": "Adding the divisors."}, {"q": "σ(pᵉ) for a prime p?", "a": "(pᵉ⁺¹ − 1)/(p − 1)", "w": ["pᵉ⁺¹", "e(p + 1)", "pᵉ − 1"], "why": "Adding the divisors."}, {"q": "m and k share no prime. σ(mk)?", "a": "σ(m)σ(k)", "w": ["σ(m) + σ(k)", "σ(m + k)", "mk"], "why": "Adding the divisors."}, {"q": "If 2ᵖ − 1 is prime, which number is perfect?", "a": "2ᵖ⁻¹(2ᵖ − 1)", "w": ["2ᵖ(2ᵖ − 1)", "2ᵖ − 1", "2ᵖ⁺¹ − 1"], "why": "Even ones, forward."}, {"q": "Is every even perfect number of that form?", "a": "yes", "w": ["no", "only the first four", "unknown"], "why": "Even ones, back."}, {"q": "An odd perfect number has which shape?", "a": "qᵏm² with q prime and q ≡ k ≡ 1 (mod 4)", "w": ["a square", "2ᵖ − 1", "a prime"], "why": "The shape of an odd one."}, {"q": "σ(n)/n is less than?", "a": "the product of p/(p − 1) over its primes", "w": ["2, always", "the number of its divisors", "n itself"], "why": "Ceilings, chains and searches."}, {"q": "Primes of the form 2ᵖ − 1. Their accepted name?", "a": "Mersenne primes", "w": ["Fermat primes", "Sophie Germain primes", "twin primes"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞61"]=[{"q": "x + y = z, sharing no prime. What is R?", "a": "the product of the different primes of xyz", "w": ["xyz", "the largest prime of z", "x + y + z"], "why": "The primes of a sum."}, {"q": "1 + (3^(2^k) − 1) = 3^(2^k). How big is z/R?", "a": "above 2^(k + 1)/3, so unbounded", "w": ["below 1", "exactly 3", "at most 2"], "why": "The primes of a sum."}, {"q": "What does abc ask?", "a": "only that z < K R^(1 + ε)", "w": ["that z < R always", "that z = R", "that R is prime"], "why": "The primes of a sum."}, {"q": "For xⁿ + yⁿ = zⁿ, why is R below z³?", "a": "R ≤ xyz < z³", "w": ["R = z", "R is prime", "x = y"], "why": "What abc would give."}, {"q": "If z < R(xyz)² always, xⁿ + yⁿ = zⁿ has no answer for n at least?", "a": "6", "w": ["3", "2", "100"], "why": "What abc would give."}, {"q": "What can a formal check settle?", "a": "whether formal definitions give a formal statement", "w": ["whether the definitions say what the words meant", "every dispute", "nothing"], "why": "What a checker could settle."}, {"q": "What can it not settle?", "a": "whether the definitions say what the words meant", "w": ["whether a step follows", "whether a statement is formal", "whether a proof is short"], "why": "What a checker could settle."}, {"q": "The claim z < K R^(1 + ε). Its accepted name?", "a": "the abc conjecture", "w": ["Fermat’s last theorem", "the Mason–Stothers theorem", "the Collatz conjecture"], "why": "The cellar."}];
