(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞64"]=[{"q": "V(t) is X(D) at which value of s?", "a": "s = t^(−1/4)", "w": ["s = t", "s = t²", "s = −t"], "why": "From the bracket to a polynomial."}, {"q": "The overhand knot has V = −t⁻⁴ + t⁻³ + t⁻¹. Its mirror?", "a": "the same with t and t⁻¹ swapped", "w": ["the same", "its negative", "1"], "why": "From the bracket to a polynomial."}, {"q": "Two rings linked once. What does their V show?", "a": "not the V of rings apart, so they stay linked", "w": ["they can be pulled apart", "nothing about linking", "they are one knot"], "why": "From the bracket to a polynomial."}, {"q": "The rule at one crossing?", "a": "t⁻¹V(L₊) − tV(L₋) = (t^(1/2) − t^(−1/2))V(L₀)", "w": ["V(L₊) = V(L₋)", "V(L₊) + V(L₋) = V(L₀)", "V(L₀) = 0"], "why": "One rule for every crossing."}, {"q": "Two knots tied one after another. V of the result?", "a": "V(K) V(L)", "w": ["V(K) + V(L)", "V(K) − V(L)", "1"], "why": "Knots tied one after another."}, {"q": "A tangle cut out, turned half a turn, and sewn back. What happens to V?", "a": "it does not change", "w": ["it is squared", "t goes to t⁻¹", "it becomes 0"], "why": "A turn the polynomial cannot see."}, {"q": "So can V tell every pair of knots apart?", "a": "no: a half turn of a tangle can change the knot and keep V", "w": ["yes", "only knots of eleven crossings", "only mirrors"], "why": "A turn the polynomial cannot see."}, {"q": "V. Its accepted name?", "a": "the Jones polynomial", "w": ["the Alexander polynomial", "the Kauffman bracket", "the HOMFLY polynomial"], "why": "The cellar."}];
