(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞66"]=[{"q": "The points y ≡ As (mod q), for A of m by n. The volume of their box?", "a": "qᵐ⁻ⁿ", "w": ["qⁿ", "qᵐ", "q"], "why": "Equations on a clock become a grid."}, {"q": "In a reduced basis of a plane lattice, |q| ≤ p ≤ r. Which vector is shortest?", "a": "the first, b₁, of value p", "w": ["the second", "their sum", "none in general"], "why": "The shortest step, in the plane."}, {"q": "When is As the only nearest point to b = As + e?", "a": "when |e| < λ₁/2", "w": ["when |e| < λ₁", "always", "when e = 0 only"], "why": "When the nearest point is the secret."}, {"q": "Adding r to the first coordinate of a and rg to b. The new samples stay noisy for the same s exactly when?", "a": "the guess g is right", "w": ["the guess g is wrong", "r = 0", "always"], "why": "Guessing one unknown at a time."}, {"q": "So on a prime clock, a method that decides gives?", "a": "a method that searches", "w": ["nothing", "a shorter lattice", "a faster clock"], "why": "Guessing one unknown at a time."}, {"q": "A bell of width s summed over the whole numbers differs from s by at most about?", "a": "2s e^(−πs²)", "w": ["s", "1/s", "e^(−s)"], "why": "A bell blurs a grid to even."}, {"q": "Finding the shortest nonzero point of a lattice. Its accepted name?", "a": "the shortest vector problem, SVP", "w": ["the knapsack problem", "the travelling salesman problem", "bounded distance decoding"], "why": "The cellar."}, {"q": "Noisy samples (a, a · s + e) on a clock. The problem of finding s. Its accepted name?", "a": "learning with errors, LWE", "w": ["the discrete log problem", "factoring", "subset sum"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞67"]=[{"q": "Adding two locks (u₁ + u₂, v₁ + v₂). What does it unlock to?", "a": "m₁ + m₂ on the clock of 2", "w": ["m₁m₂", "m₁ − m₂", "nothing"], "why": "Adding under the lock."}, {"q": "For how long does the sum unlock correctly?", "a": "while the errors stay below q/4", "w": ["for ever", "once", "while q is prime"], "why": "Adding under the lock."}, {"q": "On the whole-number lock c = pk + 2r + m, what does c₁c₂ unlock to?", "a": "m₁m₂, while |t₁t₂| < p/2", "w": ["m₁ + m₂", "nothing", "m₁, always"], "why": "Multiplying, and the errors multiply."}, {"q": "Errors of size 7 and 5, multiplied, then squared. Why does that matter past 500?", "a": "the errors multiply and soon pass the bound", "w": ["the product shrinks them", "the errors do not change", "the product only doubles them"], "why": "Multiplying, and the errors multiply."}, {"q": "When can a lock run every program?", "a": "when it runs its own unlocking plus one gate", "w": ["always, for any lock", "never, for any lock", "when it can only add"], "why": "Unlocking under the lock."}, {"q": "With shrinking, d levels of products need a clock of about?", "a": "N^(d + 2)", "w": ["N^(2^d)", "Nᵈ", "N"], "why": "Levels without refreshing."}, {"q": "Without shrinking, d levels need?", "a": "N^(2^d) or more", "w": ["N^(d + 2)", "N", "d N"], "why": "Levels without refreshing."}, {"q": "A lock that adds and multiplies locked messages. Its accepted name?", "a": "fully homomorphic encryption", "w": ["a one-time pad", "public-key signing", "a hash function"], "why": "The cellar."}];
