(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞70"]=[{"q": "The predict step for position m with speed v?", "a": "m⁻ = m + vΔt, P⁻ = P + Q", "w": ["m⁻ = m, P⁻ = 0", "m⁻ = v, P⁻ = Q", "m⁻ = m − vΔt, P⁻ = P − Q"], "why": "Predict, then correct."}, {"q": "The gain K?", "a": "P⁻/(P⁻ + R)", "w": ["R/(P⁻ + R)", "P⁻R", "P⁻ + R"], "why": "Predict, then correct."}, {"q": "The corrected guess and spread?", "a": "m = m⁻ + K(z − m⁻), P = (1 − K)P⁻", "w": ["m = z, P = R", "m = m⁻, P = P⁻", "m = Kz, P = KR"], "why": "Predict, then correct."}, {"q": "With no motion noise, what does the gain at the kth reading become?", "a": "1/k", "w": ["1", "0", "k"], "why": "Too sure of itself."}, {"q": "So what does the filter then become?", "a": "a running average, slow to follow change", "w": ["a perfect tracker", "a random walk", "a filter that ignores readings"], "why": "Too sure of itself."}, {"q": "A reading of position only. How is the speed corrected?", "a": "through the tie the prediction made", "w": ["it is not corrected", "by a second reading", "by guessing the speed"], "why": "Position and speed at once."}, {"q": "Why is the filter best with bell-shaped errors?", "a": "a bell times a bell is a bell", "w": ["bells add to bells", "errors vanish", "the gain is 1"], "why": "Best when the errors are a bell."}, {"q": "A crowd of guesses with weights wⱼ. After a reading z the weights become?", "a": "wⱼL(z | xⱼ), divided by their sum", "w": ["wⱼ unchanged", "1/n each", "wⱼ + L(z | xⱼ)"], "why": "A crowd of guesses."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞71"]=[{"q": "Plant P and controller C. What is y?", "a": "PC/(1 + PC) r", "w": ["PCr", "r/(1 + PC)", "P r/C"], "why": "The thermostat as a loop."}, {"q": "What does the running total buy?", "a": "no droop at the set point", "w": ["a brake on the swing", "more speed", "nothing at all"], "why": "Three terms, and what each buys."}, {"q": "A mass under u = Ge alone. What does adding the slope term Dé do?", "a": "it brakes the swing, so it settles", "w": ["it removes droop", "nothing", "it makes it swing for ever"], "why": "Three terms, and what each buys."}, {"q": "When does the loop settle?", "a": "when the roots of D + N lie left of Re s = 0", "w": ["when L is a real number", "when k equals 1", "always, for every k"], "why": "The curve that must not wind round −1."}, {"q": "With D having no roots on the right, how is the count found?", "a": "the clockwise winding of L(iω) round −1", "w": ["the zeros of N", "the size of L(0)", "the number of terms"], "why": "The curve that must not wind round −1."}, {"q": "The loop k/(s + 1)³ settles exactly when?", "a": "k < 8", "w": ["k < 1", "k < 3", "k > 8"], "why": "Reading the curve."}, {"q": "For k/(s + 1)², what is ∫₀^∞ ln|S(iω)| dω?", "a": "0", "w": ["1", "−∞", "k"], "why": "What no controller can do."}, {"q": "The three-term controller. Its accepted name?", "a": "the PID controller", "w": ["the Kalman filter", "the Nyquist controller", "the bang-bang controller"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞72"]=[{"q": "Two bidders, values even on [0, 1], winner pays their own bid. A best reply to a rival who bids half?", "a": "bid half your value", "w": ["bid your value", "bid nothing", "bid 1"], "why": "Bidding below your value."}, {"q": "Winner pays the second bid. What should you bid?", "a": "your value v: no other bid does better", "w": ["half your value", "nothing", "above your value"], "why": "Charge the second bid."}, {"q": "Highest value wins and the lowest pays nothing. What does a bidder of value v pay on average?", "a": "vQ(v) − ∫₀ᵛ Q", "w": ["v", "vQ(v)", "Q(v)"], "why": "The same money on average."}, {"q": "So what do the own-bid and second-bid rules raise, with two even bidders?", "a": "⅓ each", "w": ["½ and ⅓", "¼ each", "⅔ each"], "why": "The same money on average."}, {"q": "With a reserve r, the second-bid rule raises?", "a": "⅓ + r² − 4r³/3", "w": ["⅓ + r", "⅓ − r²", "r"], "why": "Sometimes refuse to sell."}, {"q": "The best reserve, and what it raises?", "a": "r = ½, raising 5/12", "w": ["r = 0, raising ⅓", "r = 1, raising 1", "r = ¼, raising ½"], "why": "Sometimes refuse to sell."}, {"q": "A and B sold in separate second-bid auctions. What can happen to a bidder who wants both?", "a": "winning exactly one at a loss", "w": ["nothing worse than winning both", "always winning both", "paying nothing"], "why": "Many goods at once."}, {"q": "The auction where the winner pays the second bid. Its accepted name?", "a": "the Vickrey auction", "w": ["the Dutch auction", "the English auction", "the first-price auction"], "why": "The cellar."}];
